insert into public.destinations ("id", "name", "category", "categoryName", "region", "location", "image", "rating", "reviews", "fee", "hours", "bestTime", "accessibility", "lat", "lng", "shortDesc", "fullDesc", "highlights", "nearbyHotels", "guideContact") values
('tafi-atome-monkey-sanctuary', 'Tafi Atome Monkey Sanctuary', 'national-parks', 'Wildlife Sanctuary', 'Volta Region', 'Tafi Atome, Hohoe District', 'assets/images/attractions/tafi-atome-monkey-sanctuary.jpg', 4.9, 840, 'GHS 60 / $5', '8:00 AM – 5:00 PM Daily', 'Early Morning (7 AM – 10 AM)', 'Easy guided walking forest path', 6.9056, 0.385, 'Sacred sanctuary where friendly Mona monkeys roam freely and interact gently with visitors in a protected tropical forest.', 'Tafi Atome Monkey Sanctuary is a community-based eco-tourism project in the Volta Region of Ghana. For over 200 years, the sacred Mona monkeys (Cercopithecus mona) have been protected by local traditional beliefs, considered divine messengers of the gods. Visitors can feed bananas to friendly monkeys right from their hands while taking guided forest walks with local community guides.', '["Hand-feeding Mona Monkeys", "Sacred Forest Walk", "Traditional Ewe Village Experience", "Community Eco-Lodge"]', '["Tafi Atome Eco-Lodge", "Wli Water Heights Lodge", "Hohoe Executive Hotel"]', '+233 24 666 4321 (Tafi Atome Eco-Desk)'),
('boabeng-fiema-monkey-sanctuary', 'Boabeng-Fiema Monkey Sanctuary', 'national-parks', 'Wildlife Sanctuary', 'Bono East', 'Nkoranza North District', 'assets/images/attractions/boabeng-fiema-monkey-sanctuary.jpg', 4.8, 720, 'GHS 70 / $6', '8:00 AM – 5:00 PM Daily', 'Year-Round (Best in dry season)', 'Shaded canopy walking trails', 7.7167, -1.7, 'Ghana''s famous sanctuary home to over 700 Mona monkeys and rare Geoffroy''s Pied Colobus monkeys living together peacefully.', 'Boabeng-Fiema is unique in Africa as the only sanctuary where two distinct species of monkeys—the Campbell''s Mona monkey and the black-and-white Geoffroy''s Pied Colobus monkey—live in close harmony near human villages. Local taboo strictly forbids harming the monkeys, and deceased monkeys are even buried with traditional funeral ceremonies in a special monkey cemetery.', '["Black & White Colobus Monkeys", "Sacred Monkey Cemetery", "Forest Canopy Nature Walk", "Nkoranza Cultural Heritage"]', '["Boabeng-Fiema Guest House", "Nkoranza Heritage Hotel", "Techiman Palace Hotel"]', '+233 20 555 9988 (Boabeng Tourism Committee)'),
('cape-coast-castle', 'Cape Coast Castle', 'historical', 'Historical Site', 'Central Region', 'Cape Coast, Atlantic Coast', 'assets/images/attractions/cape-coast-castle.jpg', 4.9, 1420, 'GHS 120 / $10', '9:00 AM – 4:30 PM Daily', 'Nov – Mar (Dry Season)', 'Wheelchair accessible lower courtyard', 5.1053, -1.2417, 'UNESCO World Heritage fortress standing over the Atlantic Ocean, preserving deep historical memory and colonial architecture.', 'Cape Coast Castle is one of about forty slave castles built on the Gold Coast of West Africa by European traders. Originally built by the Swedes in 1653 and later taken over by the British, it served as a major hub for the transatlantic slave trade. Visitors experience guided tours through the historic dungeons, the infamous ''Door of No Return'', and the upper museum detailing West African maritime history.', '["Door of No Return", "Historical Museum", "Cannon Ramparts", "Atlantic Ocean View"]', '["Coconut Grove Beach Resort", "Ridge Royal Hotel", "Oasis Beach Resort"]', '+233 24 555 0192 (GTA Certified Guide)'),
('kakum-national-park', 'Kakum National Park Canopy Walk', 'national-parks', 'National Park', 'Central Region', 'Cape Coast / Abrafo', 'assets/images/attractions/kakum-national-park.jpg', 4.8, 2180, 'GHS 150 / $12', '6:00 AM – 4:00 PM Daily', 'Early Morning (6 AM – 9 AM)', 'Moderate physical hiking involved', 5.35, -1.3833, 'Suspended 40 meters above the jungle floor, Kakum offers Africa''s most famous rainforest canopy walkway experience.', 'Kakum National Park covers 375 square kilometers of virgin tropical rainforest in southern Ghana. It is one of only three locations in Africa with a canopy walkway. Suspended across 7 tree-top bridges extending over 330 meters, visitors enjoy panoramic views of ancient hardwoods, rare birds, butterflies, and forest flora.', '["7-Bridge Canopy Walkway", "Guided Birdwatching", "Camping Grounds", "Rainforest Nature Trails"]', '["Kakum Rainforest Lodge", "Hans Cottage Botel", "Elmina Beach Resort"]', '+233 20 888 1234 (Ranger Desk)'),
('wli-waterfall', 'Wli Waterfalls', 'waterfalls', 'Waterfall', 'Volta Region', 'Hohoe, Volta Region', 'assets/images/attractions/wli-waterfall.jpg', 4.9, 950, 'GHS 80 / $7', '7:00 AM – 5:00 PM Daily', 'April – October (Peak Flow)', 'Flat 45-min jungle walk to Lower Falls', 7.1219, 0.5906, 'The highest waterfall in West Africa, cascading dramatically from a cliff face down into a fresh natural pool.', 'Wli Waterfall (locally known as Agumatsa Falls, meaning ''Allow Me to Flow'') drops over 80 meters down a sheer vertical rock face in the Agumatsa Wildlife Sanctuary. Surrounded by lush forest home to thousands of fruit bats, butterflies, and monkeys, visitors can swim in the cool, refreshing natural plunge pool.', '["Lower & Upper Falls Hike", "Fruit Bat Colony Sanctuary", "Natural Swimming Pool", "Agumatsa Forest Trail"]', '["Wli Water Heights Lodge", "Waterfall Sanctuary Lodge", "Gbadzeme Eco-Lodge"]', '+233 54 321 9876 (Wli Tourism Board)'),
('mole-national-park', 'Mole National Park Elephant Safari', 'national-parks', 'National Park', 'Savannah Region', 'Damongo, Northern Ghana', 'assets/images/attractions/mole-national-park.jpg', 4.9, 1640, 'GHS 200 / $16', '6:00 AM – 5:30 PM (Safari Hours)', 'Dec – April (Dry Season for Wildlife)', '4x4 Vehicle & Foot Safaris Available', 9.256, -1.849, 'Ghana''s largest wildlife refuge offering walking foot safaris alongside wild African elephants, antelopes, and baboons.', 'Spanning nearly 5,000 square kilometers of savannah wood and riparian forest, Mole is Ghana''s premier wildlife destination. It is famous for its close-up walking safaris where visitors can approach peaceful herds of wild African elephants on foot with experienced armed rangers.', '["Walking Foot Safaris", "Drive Safaris (4x4)", "Mole Motel Pool Outlook", "Larabanga Mosque Nearby"]', '["Zaina Lodge (Luxury Safari)", "Mole Motel", "Damongo Guest House"]', '+233 24 900 1122 (Park Headquarters)'),
('black-star-square', 'Black Star Square & Independence Arch', 'cultural', 'Cultural Landmark', 'Greater Accra', 'Accra Central Coast', 'assets/images/attractions/black-star-square.jpg', 4.7, 3100, 'Free Entry', 'Open 24/7 (Best during day)', 'Year-Round (Best at sunset)', 'Fully Paved & Accessible', 5.5486, -0.1931, 'The monumental heart of modern Ghana''s independence movement featuring the Black Star Gate and Eternal Flame.', 'Commissioned by Kwame Nkrumah to honor Ghana''s 1957 independence as the first sub-Saharan African nation to gain freedom from colonial rule. The site features the massive Black Star Gate, Independence Arch, the Flame of African Liberation, and seating for 30,000 spectators overlooking the Gulf of Guinea.', '["Independence Arch", "Black Star Gate", "Kwame Nkrumah Park Nearby", "Oceanfront Esplanade"]', '["M\u00f6venpick Ambassador Hotel", "Kempinski Hotel Gold Coast City", "Alisa Hotel"]', '+233 30 222 4455 (Accra City Tours)'),
('paga-crocodile-pond', 'Paga Sacred Crocodile Pond', 'cultural', 'Sacred Sanctuary', 'Upper East', 'Paga, Burkina Faso Border', 'assets/images/attractions/paga-crocodile-pond.jpg', 4.6, 580, 'GHS 50 / $4', '8:00 AM – 5:00 PM Daily', 'Dry Season (Nov – May)', 'Flat terrain near pond', 10.9936, -1.1128, 'Famous sacred pond where wild West African crocodiles live peacefully alongside villagers and visitors can pose with them.', 'Paga Crocodile Pond in northern Ghana is famous worldwide for its friendly, sacred crocodiles. According to local legend, the soul of every resident in Paga is tied to a crocodile in the pond. Guided by traditional caretakers, visitors can safely touch, pose with, and sit near tame crocodiles that emerge from the water.', '["Posing with Sacred Crocodiles", "Paga Slave Camp Nearby", "Burkina Border Market", "Nania Slave Route"]', '["Paga Eco-Lodge", "Navrongo Catering Rest House", "Bolgatanga Plaza Hotel"]', '+233 24 777 3311 (Paga Tourism Center)'),
('nzulezo-stilt-village', 'Nzulezo Stilt Village', 'historical', 'UNESCO Heritage Site', 'Western Region', 'Beyin, Lake Tadane', 'assets/images/attractions/nzulezo-stilt-village.jpg', 4.8, 890, 'GHS 100 / $8', '8:00 AM – 4:00 PM Daily', 'Rainy Season (Best water levels)', 'Canoe trip required across lake', 5.0167, -2.6, 'Ancient 500-year-old village built entirely on wooden stilts standing over Lake Tadane in western Ghana.', 'Nzulezo (meaning ''Surface of Water'' in the Nzema language) is a remarkable village built entirely on stilts over Lake Tadane. Founded over 500 years ago by migrants from Oualata, all structures, school, church, and walkways are suspended above the water. Visitors take a scenic 45-minute traditional canoe ride through raffia palm channels to reach the village.', '["Lake Tadane Canoe Ride", "Stilt Architecture & School", "Raffia Palm Jungle Canal", "Beyin Fort Apollonia"]', '["Maaha Beach Resort", "Lou Moon Eco-Lodge", "Beyin Beach Hotel"]', '+233 24 333 8822 (Nzulezo Tourist Board)'),
('mount-afadjato', 'Mount Afadja (Afadjato)', 'national-parks', 'Adventure Mountain', 'Volta Region', 'Liati Wote, Gbledi', 'assets/images/attractions/mount-afadjato.jpg', 4.8, 1100, 'GHS 70 / $6', '6:00 AM – 4:00 PM Daily', 'Early Morning (Clear summit views)', 'Strenuous mountain hike', 7.1167, 0.5833, 'The highest mountain peak in Ghana (885m), offering breathtaking summit views over Togo and the Volta forest.', 'Mount Afadja (commonly called Afadjato) stands at 885 meters (2,904 ft) above sea level, making it the highest elevation in Ghana. Located near the Togo border, a challenging 2-hour summit hike rewards adventurers with panoramic views of lush mountain valleys, Tagbo Falls, and surrounding tropical rain forest.', '["Summit Peak View of Togo", "Tagbo Waterfall Hike", "Liati Wote Butterfly Sanctuary", "Mountain Trekking Trail"]', '["Tagbo Falls Lodge", "Hohoe Executive Hotel", "Wli Sanctuary Lodge"]', '+233 20 444 5566 (Liati Wote Eco-Desk)'),
('boti-waterfalls', 'Boti Waterfalls & Umbrella Rock', 'waterfalls', 'Waterfall', 'Eastern Region', 'Yilo Krobo, Koforidua', 'assets/images/attractions/boti-waterfalls.jpg', 4.7, 1250, 'GHS 80 / $7', '8:00 AM – 5:00 PM Daily', 'June – October (Twin Falls Flow)', '250 stone steps to falls base', 6.1667, -0.2167, 'Famous twin waterfalls (''Male and Female'') nestled in the Huhunya forest alongside the gravity-defying Umbrella Rock.', 'Boti Falls is a seasonal twin waterfall located in the Eastern Region. The twin falls are referred to locally as the ''Male'' and ''Female'' falls; during high flow in the rainy season, they merge together in a sacred ''mating ceremony''. A 30-minute hike from the falls leads to the famous Umbrella Rock and a three-headed palm tree.', '["Twin Falls Mating Ceremony", "Umbrella Rock Balancing Formation", "3-Headed Palm Tree", "Forest Hike"]', '["Mac-Dic Royal Plaza Koforidua", "Capital View Hotel", "Boti Eco-Lodge"]', '+233 24 111 6655 (Boti Falls Tourist Desk)'),
('elmina-castle', 'Elmina Castle (St. George''s Castle)', 'historical', 'UNESCO Heritage Site', 'Central Region', 'Elmina, Central Coast', 'assets/images/attractions/elmina-castle.jpg', 4.9, 1890, 'GHS 120 / $10', '9:00 AM – 4:30 PM Daily', 'Year-Round', 'Paved courtyards & historic stairs', 5.0844, -1.3492, 'The oldest European building in existence in sub-Saharan Africa, erected by the Portuguese in 1482.', 'St. George''s Castle in Elmina was constructed by Portuguese traders in 1482 as the first European trading post built on the Gulf of Guinea. Initially established for gold trading, it later became a central site of the transatlantic slave trade under Dutch and British control. Today, it stands as a UNESCO World Heritage site and powerful monument of remembrance.', '["Portuguese & Dutch Dungeons", "Female Slave Cells", "Governor''s Suite", "Elmina Fishing Harbor Overlook"]', '["Elmina Beach Resort", "Coconut Grove Beach Resort", "Golden Hill Parker Hotel"]', '+233 24 888 7766 (Elmina Castle Desk)'),
('larabanga-mosque', 'Larabanga Ancient Mosque', 'historical', 'Architectural Heritage', 'Savannah Region', 'Larabanga, near Mole Park', 'assets/images/attractions/larabanga-mosque.jpg', 4.7, 640, 'GHS 40 / $3', '8:00 AM – 5:30 PM Daily', 'Dry Season (Combines with Mole Safari)', 'Flat village walking access', 9.2197, -1.8603, 'Ghana''s oldest mosque built in 1421 in Sudanic-Sahelian architectural style, known as the ''Mecca of West Africa''.', 'Larabanga Mosque is an ancient mud-brick mosque founded in 1421 by Islamic trader Ayuba. Built using whitewashed mud, timber logs, and pyradmidal towers, it is the oldest existing mosque in Ghana and one of the most famous examples of Sudanic architecture in West Africa. It houses an ancient Koran believed to have descended from heaven.', '["Sudanese Mud-Brick Architecture", "Ancient Holy Koran Replica", "Larabanga Mystic Stone", "Mole Safari Stopover"]', '["Zaina Lodge", "Mole Motel", "Damongo Guest House"]', '+233 24 555 4321 (Larabanga Tourism Guild)'),
('aburi-botanical-gardens', 'Aburi Botanical Gardens', 'national-parks', 'Botanical Reserve', 'Eastern Region', 'Aburi, Akuapem Hills', 'assets/images/attractions/aburi-botanical-gardens.jpg', 4.7, 1950, 'GHS 50 / $4', '8:30 AM – 5:00 PM Daily', 'Year-Round (Cool mountain breeze)', 'Wide paved garden avenues', 5.8483, -0.1747, 'Historic 1890s hilltop garden retreat nestled in the cool Akuapem mountains featuring giant palm avenues and exotic trees.', 'Established in 1890 by the British colonial administration, Aburi Botanical Gardens spans 160 acres of lush mountain forest. Known for its majestic royal palm avenue, carved tree of life, exotic medicinal plants, and cool temperate climate, Aburi is a favorite weekend getaway just 45 minutes drive from Accra.', '["Royal Palm Tree Avenue", "Carved Tree of Life", "Old Helicopter Monument", "Cocoa Tree Demonstration Plot"]', '["Peduase Valley Resort", "Aburi Heights Hotel", "Hillburi Resort"]', '+233 20 222 9988 (Aburi Gardens Desk)'),
('bonwire-kente-village', 'Bonwire Kente Weaving Village', 'cultural', 'Craft Heritage', 'Ashanti Region', 'Bonwire, near Kumasi', 'assets/images/attractions/bonwire-kente-village.jpg', 4.8, 810, 'Free Entry (Shopping extra)', '8:00 AM – 5:00 PM (Mon – Sat)', 'Year-Round', 'Village workshop walking paths', 6.7833, -1.4833, 'The historic heartland of royal Ashanti Kente cloth weaving, where master weavers craft silk fabrics on wooden looms.', 'Bonwire is world-famous as the birth village of Kente cloth weaving in the Ashanti Kingdom. Legend has it that two brothers learned the art by observing a spider weaving its web. Today, visitors can watch master craftsmen operate hand looms, try weaving their own patterns, and purchase authentic royal Kente directly from artisan families.', '["Live Hand-Loom Weaving", "Custom Kente Ordering", "Kente Origin Legends", "Bonwire Kente Museum"]', '["Manhyia Palace Hotel", "Golden Tulip Kumasi", "Royal Basin Resort"]', '+233 24 444 1199 (Bonwire Weavers Guild)'),
('kwame-nkrumah-mausoleum', 'Kwame Nkrumah Memorial Park & Mausoleum', 'cultural', 'National Memorial', 'Greater Accra', 'Accra Central', 'assets/images/attractions/kwame-nkrumah-mausoleum.jpg', 4.5, 0, 'Free Entry', 'Open Daily', 'Year-Round', 'Generally accessible', 5.5489, -0.1907, 'The final resting place of Ghana''s first president, featuring a bronze statue, eternal flame, and seaside gardens in the heart of Accra.', 'Kwame Nkrumah Memorial Park occupies the site where Ghana''s founding father and first president, Dr. Kwame Nkrumah, and his wife Fathia were laid to rest. Set near the Old Parliament on the Accra shoreline, the park pairs a dignified mausoleum and statue with tranquil gardens and the ocean outlook, telling the story of Ghana''s independence movement.', '["Bronze Statue of Nkrumah", "Eternal Flame", "Independence Garden Walk", "Accra Seafront Views"]', '[]', ''),
('manhyia-palace', 'Manhyia Palace Museum', 'historical', 'Royal Museum', 'Ashanti Region', 'Kumasi', 'assets/images/attractions/manhyia-palace.jpg', 4.5, 0, 'Free Entry', 'Open Daily', 'Year-Round', 'Generally accessible', 6.7492, -1.587, 'The royal residence of the Ashanti kings of Kumasi, now a museum of Asante history, regalia, and court culture.', 'Manhyia Palace was built in 1925 as the new royal residence for the Ashanti monarch and has long been the ceremonial seat of the Asantehene of Kumasi. Today it operates as a museum preserving royal regalia, photographs, ceremonial stools, and the personal effects of successive Ashanti kings, offering visitors a vivid window into Asante court life.', '["Royal Regalia Exhibits", "Asantehene History", "Ceremonial Stools", "Kumasi Culture Overview"]', '[]', ''),
('lake-bosomtwe', 'Lake Bosomtwe Crater Lake', 'waterfalls', 'Crater Lake', 'Ashanti Region', 'Lake Bosomtwe, near Kumasi', 'assets/images/attractions/lake-bosomtwe.jpg', 4.5, 0, 'Free Entry', 'Open Daily', 'Year-Round', 'Generally accessible', 6.5189, -1.466, 'A sacred circular crater lake, formed by a meteorite impact, ringed by lakeside villages and lively weekend boat trade.', 'Lake Bosomtwe lies within a 10.5 km meteorite crater surrounded by hilly Ashanti farmland. The lake has no outlet and is culturally sacred to the surrounding Asante villages, which fish it with traditional plank boats and canoes. Weekends draw families for boating, swimming, and lakeside picnics among the crater walls.', '["Crater Lake Boat Ride", "Sacred Lake Swimming", "Lakeside Village Walks", "Meteorite Crater Geology"]', '[]', ''),
('ahwiaa-woodcarving-village', 'Ahwiaa Woodcarving Village', 'cultural', 'Craft Village', 'Ashanti Region', 'Ahwiaa, near Kumasi', 'assets/images/attraction-placeholder.svg', 4.5, 0, 'Free Entry', 'Open Daily', 'Year-Round', 'Generally accessible', 6.68, -1.54, 'A village of master carvers producing ceremonial Ashanti stools, royal figures, and fine wooden sculptures by hand.', 'Ahwiaa (Ahuwa) is Ghana''s leading woodcarving village, where families have carved for generations with simple chisels and scrapers. Craftspeople fashion the famous Ashanti ceremonial stools, filigree dancing stools, chiefs'' figures, and masks from tropical hardwoods, and welcome visitors to watch and commission pieces.', '["Live Carving Demonstrations", "Ceremonial Stools", "Custom Commission Ordering", "Ashanti Motifs"]', '[]', ''),
('fort-apollonia', 'Fort Apollonia', 'historical', 'UNESCO Heritage Site', 'Western Region', 'Beyin, near Nzulezo', 'assets/images/attractions/fort-apollonia.jpg', 4.5, 0, 'Free Entry', 'Open Daily', 'Year-Round', 'Generally accessible', 5.024, -2.6, 'An 18th-century frontier fort turned regional museum, overlooking the journey to the Nzulezo stilt village.', 'Fort Apollonia was built by the Dutch around 1768 on a ridge above Beyin to guard trade routes on the Ankobra towards the Nzulezo lake. It was gutted by fire in the late 19th century and today its restored walls hold the Beyin Regional Museum, which traces the culture of the Nzema people and the surrounding natural landscape.', '["Restored Fort Ramparts", "Beyin Regional Museum", "Nzema Culture Exhibits", "Views over Lake Tadane"]', '[]', ''),
('ankasa-forest-reserve', 'Ankasa Conservation Area', 'national-parks', 'Rainforest & Wetland', 'Western Region', 'Near Axim / Elubo', 'assets/images/attractions/ankasa-forest-reserve.jpg', 4.5, 0, 'Free Entry', 'Open Daily', 'Year-Round', 'Generally accessible', 5.27, -2.7, 'A pristine wet-evergreen rainforest and wetland near the Ivory Coast border, rich in primates, birds, and rare flora.', 'Ankasa Conservation Area in Ghana''s far southwest protects wet evergreen forest and the large Tanoe wetland system. It shelters Congo clawless otters, forest elephants, bongo antelopes, and abundant bird species along forest trails and the Ankobra watershed, offering guided nature walks into one of West Africa''s most biologically rich forests.', '["Guided Forest Walk", "Rare Birding", "Wetland Canoe Trails", "Primates & Wildlife"]', '[]', ''),
('sekondi-takoradi-beach', 'Sekondi-Takoradi Beach', 'coastal', 'Coastal Beach', 'Western Region', 'Sekondi-Takoradi', 'assets/images/attractions/sekondi-takoradi-beach.jpg', 4.5, 0, 'Free Entry', 'Open Daily', 'Year-Round', 'Generally accessible', 4.9, -1.76, 'Long golden-sand beaches and lagoons along the Sekondi-Takoradi coast, a relaxed seaside stretch of Ghana''s west.', 'The Sekondi-Takoradi coastline is lined with clean beaches, lagoon systems, and fishing communities. The palm-backed sands and gentle surf make it a favourite local getaway, with beachfront stalls serving fresh coconut and grilled fish and evening views over the Gulf of Guinea.', '["Golden Sand Beach", "Fresh Coconut Stalls", "Lagoon Walks", "Gulf of Guinea Sunsets"]', '[]', ''),
('techiman-history-museum', 'Techiman Heritage & Culture Museum', 'cultural', 'Heritage Museum', 'Bono Region', 'Techiman', 'assets/images/attraction-placeholder.svg', 4.5, 0, 'Free Entry', 'Open Daily', 'Year-Round', 'Generally accessible', 7.59, -2.01, 'A community museum preserving the royal history, shrines, and oral traditions of the historic Bono (Brong) kingdom.', 'Techiman is the heart of the historic Bono (Brong) kingdom and its traditional area. The heritage museum gathers royal regalia, shrine artefacts, textiles, and the drumming traditions associated with the famous Apoo festival, giving visitors insight into one of Ghana''s oldest monarchical states.', '["Royal Regalia", "Apoo Festival Artefacts", "Brong Oral History", "Traditional Shrines"]', '[]', ''),
('kintampo-waterfalls', 'Kintampo Waterfalls', 'waterfalls', 'Waterfall', 'Bono East', 'Kintampo', 'assets/images/attractions/kintampo-waterfalls.jpg', 4.5, 0, 'Free Entry', 'Open Daily', 'Year-Round', 'Generally accessible', 8.16, -1.95, 'A series of cascades at the source of the Pumpum River, hidden in dense forest on the Kintampo plateau.', 'Kintampo Waterfulls are formed where the Pumpum River drops over a rocky outcrop in gallery forest, creating a chain of falls and plunge pools. Long a favourite picnic and trekking spot, the site offers nature trails, swimming holes, and the lush Kintampo Plateau scenery between the forested ravines.', '["Multiple Cascade Viewpoints", "Natural Swimming Pools", "Forest Nature Trails", "Kintampo Plateau Picnic"]', '[]', ''),
('gbewaa-palace', 'Gbewaa Palace (Daboya)', 'historical', 'Royal Site', 'Northern Region', 'Daboya, near Tamale', 'assets/images/attractions/gbewaa-palace.jpg', 4.5, 0, 'Free Entry', 'Open Daily', 'Year-Round', 'Generally accessible', 9.41, -0.75, 'The ancestral palace of the Dagbon kings, sacred to the royal Kayayei and the Damba festival traditions.', 'Gbewaa is the historic seat of the Dagbon (Dagbamba) royal family of Tamale. The palace compound holds royal graves and shrine houses, and remains the spiritual anchor of the Damba festival with its horse-riding displays and drumming. Visitors can trace the living heritage of northern Ghana''s chiefs.', '["Royal Palace Compound", "Dagbon Royal Graves", "Damba Festival Trails", "Northern Chieftaincy History"]', '[]', ''),
('navrongo-basilica', 'Navrongo Catholic Basilica', 'historical', 'Historic Church', 'Upper East', 'Navrongo', 'assets/images/attractions/navrongo-basilica.jpg', 4.5, 0, 'Free Entry', 'Open Daily', 'Year-Round', 'Generally accessible', 10.9, -1.08, 'Ghana''s oldest permanent Catholic structure, a red-brick basilica completed in 1906 by White Fathers missionaries.', 'The Basilica of Our Lady of Seven Sorrows in Navrongo is the oldest Catholic church in Ghana, built between 1882 and 1906 by the White Fathers in red-brick Romanesque style. Now a minor basilica with a bishop''s seat, it anchors the Christian heritage of the Upper East against the region''s Muslim and traditional histories.', '["Historic Basilica Walls", "1906 Mission Architecture", "Catholic Heritage Museum", "Navrongo Town Views"]', '[]', ''),
('bolgatanga-basketry-village', 'Bolgatanga Basket Weaving Village', 'cultural', 'Craft Village', 'Upper East', 'Bolgatanga', 'assets/images/attractions/bolgatanga-basketry-village.jpg', 4.5, 0, 'Free Entry', 'Open Daily', 'Year-Round', 'Generally accessible', 10.78, -1.25, 'The heartland of the famous Bolga baskets, where women weave vibrantly coloured grasses into export-quality baskets.', 'Bolgatanga (Bolgatanga) in the Upper East is famous across global retail for its brightly striped woven baskets. Local women harvest and dye elephant grass and weave intricate baskets, hampers, and homewares that are exported worldwide. Visitors can watch weaving and buy direct from the artisans'' cooperative.', '["Live Basket Weaving", "Bolgatanga Cooperative", "Direct Artisan Purchase", "Grass Dyeing Craft"]', '[]', ''),
('nania-slave-route', 'Nania Slave Route', 'historical', 'Heritage Trail', 'Upper East', 'Nania, near Paga', 'assets/images/attraction-placeholder.svg', 4.5, 0, 'Free Entry', 'Open Daily', 'Year-Round', 'Generally accessible', 10.85, -1.1, 'A preserved section of the historic overland slave route with iron neck-ring trees and memorial stones.', 'Nania marks a chain of historic sites connected to the trans-Saharan slave trade across northern Ghana. Remnants include the famed iron neck-ring tree where captives were shackled, storage pits, and memorial stones. Interpretive trails place the painful history of the region''s slave routes in context.', '["Neck-Ring Tree", "Slave Route Trail", "Memorial Stones", "Guided Heritage Talk"]', '[]', ''),
('mount-gemi', 'Mount Gemi', 'national-parks', 'Adventure Mountain', 'Volta Region', 'Gbledi, near Afadjato', 'assets/images/attractions/mount-gemi.jpg', 4.5, 0, 'Free Entry', 'Open Daily', 'Year-Round', 'Generally accessible', 7.15, 0.68, 'The second-highest peak in Ghana, offering a steep forested ascent and views over the Togo borderland.', 'Mount Gemi (Afadja''s sibling peak) is one of southern Ghana''s highest summits, approached through misty montane forest near Afadjato. The climb rewards trekkers with panoramas across the Volta highlands and across the border into Togo, passing waterfalls and remnant forest along the ridge.', '["Summit Panorama", "Forest Trekking", "Togo Border Views", "Highland Birding"]', '[]', ''),
('tagbo-falls', 'Tagbo Falls', 'waterfalls', 'Waterfall', 'Volta Region', 'Liati Wote, near Afadjato', 'assets/images/attractions/tagbo-falls.jpg', 4.5, 0, 'Free Entry', 'Open Daily', 'Year-Round', 'Generally accessible', 7.09, 0.55, 'A slender high cascade in the Afadjato highlands, best in the rainy season when the forest pools swell.', 'Tagbo Falls tumbles down a high rock face in the forested hills below Mount Afadjato. Its flow peaks after rains, creating frothing plunge pools and mist. The falls can be reached on foot from Liati Wote and combine naturally with the Afadjato summit and Gemi climbs on a mountain day-trip.', '["High Plunge Cascade", "Afadjato Combo Trek", "Forest Pools", "Highland Scenery"]', '[]', ''),
('bunso-eco-park', 'Bunso Honey & Palm Wine Eco-Park', 'national-parks', 'Eco-Park', 'Eastern Region', 'Bunso, Akuapem Ridge', 'assets/images/attraction-placeholder.svg', 4.5, 0, 'Free Entry', 'Open Daily', 'Year-Round', 'Generally accessible', 6.32, -0.35, 'A nature and cultural park on the Akuapem ridge offering honey tasting, palm-wine trails, and lush walks.', 'Bunso Eco-Park sits on the heights of the Akuapem ridge in the Eastern Region. The park blends nature trails with revived traditions: a palm-wine distilling walk, honey production hives, and forest foraging experiences, all set within the cool mountain greenery of the Akuapem range.', '["Palm Wine Trail", "Honey Tasting", "Akuapem Ridge Walks", "Forest Gardening"]', '[]', ''),
('dambai-lake-volta', 'Lake Volta Shore at Dambai', 'national-parks', 'Lake & Jetty', 'Oti Region', 'Dambai, Oti', 'assets/images/attraction-placeholder.svg', 4.5, 0, 'Free Entry', 'Open Daily', 'Year-Round', 'Generally accessible', 7.3, 0.1, 'The great artificial Lake Volta spreading out at Dambai, with fishing canoes and grand waterfront sunsets.', 'Dambai is the seat of the Oti region on the shore of Lake Volta, one of the world''s largest artificial reservoirs. The waterfront bustles with fishing canoes, ferries, and markets, and the broad lake horizon offers some of Ghana''s largest water vistas and sunsets.', '["Lake Volta Vistas", "Fishing Canoe Harbour", "Waterfront Markets", "Volta Sunsets"]', '[]', ''),
('gambaga-escarpment-lookout', 'Gambaga Lookout & Nahiley Escarpment', 'national-parks', 'Scenic Viewpoint', 'North East', 'Nalerigu / Gambaga', 'assets/images/attraction-placeholder.svg', 4.5, 0, 'Free Entry', 'Open Daily', 'Year-Round', 'Generally accessible', 10.5, -0.42, 'Verdant escarpment viewpoints over the Mamprusi heartland and the rolling North East countryside.', 'The Gambaga-Nahiley escarpment in Ghana''s North East rises over the Mamprusi traditional area, with lookout points across dense farmland and hillside settlements. Its cool heights, waterfalls in the rains, and traditional towns make for scenic highland touring.', '["Escarpment Lookouts", "Mamprusi Farmland Views", "Hilltown Walks", "Rainy-Season Cascades"]', '[]', ''),
('wa-naa-palace', 'Wa Naa Palace', 'historical', 'Royal Site', 'Upper West', 'Wa, Upper West', 'assets/images/attractions/wa-naa-palace.jpg', 4.5, 0, 'Free Entry', 'Open Daily', 'Year-Round', 'Generally accessible', 10.95, -2.55, 'The old seat of the Wa Naa paramount chief, with preserved royal court buildings and northern savannah surroundings.', 'Wa Naa Palace in the far northwest recalls the chieftaincy system of the Waala (Wali) people. The compound retains traditional royal court structures and serves as a centre of local history near the regional capital, set amid the dry savannah of Ghana''s Upper West.', '["Royal Court Buildings", "Northern Savannah Setting", "Waala Chieftaincy History", "Central Architectural Style"]', '[]', ''),
('sefwi-wiawso-palace', 'Sefwi Wiawso Paramount Chief''s Palace', 'cultural', 'Royal Site', 'Western North', 'Sefwi Wiawso, Western North', 'assets/images/attraction-placeholder.svg', 4.5, 0, 'Free Entry', 'Open Daily', 'Year-Round', 'Generally accessible', 6.2, -2.97, 'The traditional seat of the Sefwi paramount chieftaincy, set amid the forested hills of Ghana''s far west.', 'Sefwi Wiawso is the historic capital of the Sefwi people in Ghana''s Western North. The paramount chief''s palace compound preserves the region''s chieftaincy heritage, court structures, and surrounding cocoa-and-forest landscape, offering insight into the largely unexplored western hill country.', '[]', '[]', '+233 20 000 0000 (Wiawso Tourist Office)'),
('ahafo-cocoa-forest', 'Goaso Cocoa & Forest Belt', 'national-parks', 'Nature & Cocoa', 'Ahafo Region', 'Goaso, Ahafo Region', 'assets/images/attraction-placeholder.svg', 4.5, 0, 'Free Entry', 'Open Daily', 'Year-Round', 'Generally accessible', 6.8, -2.55, 'Rolling cocoa farms and gallery forest around Goaso, the agricultural heart of central-west Ghana.', 'The Ahafo Region around Goaso is one of Ghana''s principal cocoa-growing belts. Travelling the area reveals cocoa farms, palm swamps, and riverine forest with abundant birds, an off-the-beaten-path slice of rural Ashanti-Ahafo country.', '[]', '[]', '+233 20 000 0000 (Goaso Tourist Office)'),
